mkdir -p /tmp/claude-0/-home-user-threadgame/283326c9-5b0d-5733-99e1-670739471e16/scratchpad/p0102/tools; cat > /tmp/claude-0/-home-user-threadgame/283326c9-5b0d-5733-99e1-670739471e16/scratchpad/p0102/tools/verify.py <<'EOF'
#!/usr/bin/env python3
"""Draw band polygon (perpendicular half-widths), sprites every step of f, occluder-applied render.
usage: verify.py pid out.png [--scale s] [--crop x0,y0,x1,y1] [--step 0.05] [--approved] [--occ] [--nolines] [--fs f1,f2]"""
import argparse, json, os, subprocess, math
from PIL import Image, ImageDraw
REPO='/home/user/threadgame'; KIT=REPO+'/kit/Wishweave-Level1-Complete-Visual-Kit'
NODE=r"""
const path=require('path');const R=process.argv[1];const id=process.argv[2];const step=+process.argv[3];const extra=JSON.parse(process.argv[4]);
for(const f of ['core/ww.js','core/path.js','data/asset-data.js','data/plates/'+id+'.js'])require(path.join(R,'game/src',f));
const P=WW.PLATES[id];const S=(pts,f,l)=>WW.path.racerPoint(pts,f,l||0,0);
const out={plate:P,frames:WW.ASSETS.frames,images:WW.ASSETS.images};
out.purlW=WW.path.widths(P.purl.path); out.loopW=P.loop?WW.path.widths(P.loop.path):0;
const fs=[];for(let f=0;f<=1.0001;f+=step)fs.push(Math.min(1,f));for(const e of P.purl.events)if(typeof e.f==='number')fs.push(e.f);for(const f of extra)fs.push(f);
out.purl=fs.map(f=>({f,p:S(P.purl.path,f,0),l:S(P.purl.path,f,-1),r:S(P.purl.path,f,1)}));
const lf=[];for(let f=0;f<=1.0001;f+=step*2)lf.push(Math.min(1,f));if(P.loop)for(const e of P.loop.events)if(typeof e.f==='number')lf.push(e.f);
out.loop=P.loop?lf.map(f=>({f,p:S(P.loop.path,f,0)})):[];
out.lanes=[-1,0,1].map(l=>{const a=[];for(let i=0;i<=300;i++)a.push(S(P.purl.path,i/300,l));return a;});
out.loopLine=[];if(P.loop)for(let i=0;i<=200;i++)out.loopLine.push(S(P.loop.path,i/200,0));
console.log(JSON.stringify(out));
"""
def spr(d,cache,name,w):
    fr=d['frames'][name];k=fr['img']
    if k not in cache: cache[k]=Image.open(os.path.join(REPO,'game',d['images'][k]['file'])).convert('RGBA')
    im=cache[k].crop((fr['x'],fr['y'],fr['x']+fr['w'],fr['y']+fr['h']));s=w/fr['w']
    return im.resize((max(1,int(fr['w']*s)),max(1,int(fr['h']*s))),Image.LANCZOS),fr['px']*s,fr['py']*s
def bandpoly(band):
    L=[];R=[]
    for i,(x,y,hw) in enumerate(band):
        a=band[max(0,i-1)];b=band[min(len(band)-1,i+1)]
        tx,ty=b[0]-a[0],b[1]-a[1];n=math.hypot(tx,ty) or 1;tx/=n;ty/=n
        nx,ny=-ty,tx
        L.append((x+nx*hw,y+ny*hw));R.append((x-nx*hw,y-ny*hw))
    return L+R[::-1]
ap=argparse.ArgumentParser();ap.add_argument('pid');ap.add_argument('out');ap.add_argument('--scale',type=float,default=0.6)
ap.add_argument('--crop');ap.add_argument('--step',type=float,default=0.1);ap.add_argument('--approved',action='store_true')
ap.add_argument('--occ',action='store_true',help='apply occluders like the renderer');ap.add_argument('--nolines',action='store_true')
ap.add_argument('--fs',default='');ap.add_argument('--who',default='both')
a=ap.parse_args()
extra=[float(v) for v in a.fs.split(',') if v]
d=json.loads(subprocess.run(['node','-e',NODE,REPO,a.pid,str(a.step),json.dumps(extra)],capture_output=True,text=True,check=True).stdout)
P=d['plate']
plate=Image.open(os.path.join(REPO,'game',d['images'][P['image']]['file'])).convert('RGBA').resize((841,1870))
base=Image.open(os.path.join(KIT,'approved',P['approved'])).convert('RGBA').resize((841,1870)) if a.approved else plate.copy()
cache={}
# actors: list of (groundY, img, pos)
acts=[]
if a.who in('both','purl'):
  for s in d['purl']:
    p=s['p'];im,px,py=spr(d,cache,'purl.run-left',p['w']);acts.append((p['y'],im,(int(p['x']-px),int(p['y']-py)),'purl'))
if a.who in('both','loop'):
  for s in d['loop']:
    p=s['p'];im,px,py=spr(d,cache,'loop.run-left',p['w']);acts.append((p['y'],im,(int(p['x']-px),int(p['y']-py)),'loop'))
for e in P['purl']['events']:
    if e['type']=='pickup':
        s=[q for q in d['purl'] if abs(q['f']-e['f'])<1e-9][0]['p']
        nm='prop.%s-thread'%('golden' if e['item']=='gold' else e['item']);im,px,py=spr(d,cache,nm,e['size']);acts.append((s['y']-0.5,im,(int(s['x']-px),int(s['y']-py)),'item'))
for pv in P.get('previews',[]):
    nm='prop.%s-thread'%('golden' if pv['item']=='gold' else pv['item']);im,px,py=spr(d,cache,nm,pv['size']);acts.append((pv['y'],im,(int(pv['x']-px),int(pv['y']-py)),'item'))
if P.get('cameo'):
    c=P['cameo'];im,px,py=spr(d,cache,'snag.peek',c['w']);acts.append((c['y'],im,(int(c['x']-px),int(c['y']-py)),'snag'))
acts.sort(key=lambda t:t[0])
out=base.copy()
for gy,im,pos,who in acts:
    layer=Image.new('RGBA',out.size,(0,0,0,0));layer.alpha_composite(im,pos)
    if a.occ:
        for oc in P.get('occluders',[]):
            if gy<oc['behindY']:
                m=Image.new('L',out.size,0);ImageDraw.Draw(m).polygon([tuple(q) for q in oc['poly']],fill=255)
                al=layer.getchannel('A');al=Image.composite(Image.new('L',out.size,0),al,m);layer.putalpha(al)
    out.alpha_composite(layer)
if not a.nolines:
    ov=Image.new('RGBA',out.size,(0,0,0,0));dr=ImageDraw.Draw(ov)
    for key in('ribbon','shortcut'):
        b=(P.get(key) or {}).get('band')
        if b:
            dr.polygon(bandpoly(b),outline=(255,140,0,255),fill=(255,255,255,40))
            dr.line([(x,y) for x,y,_ in b],fill=(255,140,0,255),width=2)
