cd /tmp/claude-0/-home-user-threadgame/283326c9-5b0d-5733-99e1-670739471e16/scratchpad/p0102; cat > tools/check.js <<'EOF'
const R='/home/user/threadgame/game/src/';
for (const f of ['core/ww.js','core/path.js','data/asset-data.js','data/plates/p01.js','data/plates/p02.js']) require(R+f);
const appr={p01:{purl:[274,1518,289],loop:[726,1068,145],stopId:'ribbon'},p02:{purl:[346,1530,292],loop:[717,687,111],stopId:'shortcut'}};
for (const id of ['p01','p02']) {
  const P=WW.PLATES[id]; const A=appr[id];
  console.log('==',id,'draft' in P?'HAS DRAFT':'no draft','keys:',Object.keys(P).join(','));
  console.log(' purl widths',WW.path.widths(P.purl.path).toFixed(2),'loop widths',WW.path.widths(P.loop.path).toFixed(2), 'points', P.purl.path.length, P.loop.path.length);
  for (const e of P.purl.events) { if (!(e.f>=0&&e.f<=1)) console.log(' BAD f',e); }
  for (const e of P.loop.events) { if (!(e.f>=0&&e.f<=1)) console.log(' BAD loop f',e); }
  const stop=P.purl.events.find(e=>e.type==='stop'); const s=WW.path.sample(P.purl.path,stop.f);
  console.log(' stop', stop.stitch, 'f',stop.f,'->',s.x.toFixed(1),s.y.toFixed(1),'w',s.w.toFixed(1),'| approved',A.purl.join(','),'| d=',Math.hypot(s.x-A.purl[0],s.y-A.purl[1]).toFixed(1),'px dw=',(100*(s.w/A.purl[2]-1)).toFixed(1)+'%');
  const s0=WW.path.sample(P.purl.path,0); console.log(' f=0 ->',s0.x,s0.y,'w',s0.w,'| d=',Math.hypot(s0.x-A.purl[0],s0.y-A.purl[1]).toFixed(1), 'zoom at stop', (s0.w/s.w).toFixed(3));
  const lf=WW.path.project(P.loop.path,A.loop[0],A.loop[1]); const ls=WW.path.sample(P.loop.path,lf);
  console.log(' loop passes approved at f',lf.toFixed(3),'->',ls.x.toFixed(1),ls.y.toFixed(1),'w',ls.w.toFixed(1),'| approved',A.loop.join(','),'d=',Math.hypot(ls.x-A.loop[0],ls.y-A.loop[1]).toFixed(1));
  const st=P.stitch; console.log(' stitch',JSON.stringify(st),'dist from stop',Math.hypot(st.x-s.x,st.y-s.y).toFixed(0));
  for (const e of P.purl.events.filter(e=>e.type==='pickup')) { const q=WW.path.sample(P.purl.path,e.f); console.log(' pickup',e.item,'f',e.f,'->',q.x.toFixed(1),q.y.toFixed(1),'w',q.w.toFixed(1),'size',e.size); }
  for (const e of P.loop.events) { const q=WW.path.sample(P.loop.path,e.f); console.log(' loop',e.type,e.kind||e.item,'f',e.f,'->',q.x.toFixed(1),q.y.toFixed(1),'w',q.w.toFixed(1), JSON.stringify(e)); }
  if (P.previews) for (const pv of P.previews) { let best=1e9; for (let i=0;i<=400;i++){const q=WW.path.sample(P.purl.path,i/400); best=Math.min(best,Math.hypot(q.x-pv.x,q.y-pv.y));} console.log(' preview',pv.item,'min distance from Purl path',best.toFixed(0),'px'); }
  // occluder sanity: Purl sample sprites vs occluders (bbox overlap with ground y < behindY)
  const inPoly=(x,y,poly)=>{let c=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const [xi,yi]=poly[i],[xj,yj]=poly[j];if(((yi>y)!=(yj>y))&&(x<(xj-xi)*(y-yi)/(yj-yi)+xi))c=!c;}return c;};
  for (const o of P.occluders) for (const [who,pts,lanes] of [['purl',P.purl.path,[-1,0,1]],['loop',P.loop.path,[0]]]) {
    const hits=[]; for (let i=0;i<=200;i++) for (const l of lanes) { const q=WW.path.racerPoint(pts,i/200,l,0); if (q.groundY>=o.behindY) continue;
      // sample the sprite box
      let n=0; for (let dx=-0.45;dx<=0.45;dx+=0.15) for (let dy=0.05;dy<=1;dy+=0.15) if (inPoly(q.x+dx*q.w,q.groundY-dy*q.w,o.poly)) n++;
      if (n) hits.push((i/200).toFixed(3)+'@'+l); }
    console.log(' occluder',o.id,'hides',who,'at',hits.length?hits[0]+'..'+hits[hits.length-1]+' ('+hits.length+')':'never');
  }
}
EOF
node tools/check.js

